use std::fs::{self, OpenOptions};
use std::io::{self, Write};
use std::path::Path;

/// Replace `path` with `contents`: write a temporary file next to it, then rename it over.
fn save_atomic(path: &Path, contents: &str) -> io::Result<()> {
    let mut name = path.file_name().expect("a file path").to_owned();
    name.push(format!(".{}.tmp", std::process::id()));
    let tmp = path.with_file_name(name); // same directory, so the same file system

    // create_new fails if the name is taken, so we never touch a file that is not ours
    let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;

    // a closure that is called at once: `?` leaves the closure, not save_atomic,
    // so the clean-up below runs on any error
    let result = (|| {
        f.write_all(contents.as_bytes())?;
        f.sync_all()?; // ask the OS to put the bytes on the disk before the swap
        fs::rename(&tmp, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&tmp); // do not leave the temporary file behind
    }
    result
}

fn names(dir: &Path) -> io::Result<Vec<String>> {
    let mut names = Vec::new();
    for entry in fs::read_dir(dir)? {
        names.push(entry?.file_name().to_string_lossy().into_owned());
    }
    names.sort();
    Ok(names)
}

fn main() -> io::Result<()> {
    let dir = std::env::temp_dir().join("lr-atomic");
    fs::create_dir_all(&dir)?;
    let config = dir.join("config.txt");

    fs::write(&config, "version 1\n")?;
    save_atomic(&config, "version 2\n")?;
    println!("config: {:?}", fs::read_to_string(&config)?);
    println!("directory after the save: {:?}", names(&dir)?);

    // a save that fails: the target is a directory, so the rename is refused
    let blocked = dir.join("blocked");
    fs::create_dir(&blocked)?;
    let err = save_atomic(&blocked, "x").unwrap_err();
    println!("save over a directory: {:?}", err.kind());
    println!("directory after the failed save: {:?}", names(&dir)?);

    fs::remove_dir_all(&dir)
}

buffering.rs.code:
use std::io::{self, BufWriter, Write};

/// A destination that only counts how many times it is asked to write.
struct Counting {
    calls: usize,
    bytes: usize,
}

impl Write for Counting {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.calls += 1;
        self.bytes += buf.len();
        Ok(buf.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let mut raw = Counting { calls: 0, bytes: 0 };
    for i in 0..1000 {
        writeln!(raw, "line {i}")?;
    }
    println!(
        "unbuffered: {} bytes in {} write calls",
        raw.bytes, raw.calls
    );

    let mut w = BufWriter::new(Counting { calls: 0, bytes: 0 });
    println!("capacity: {}", w.capacity());
    for i in 0..1000 {
        writeln!(w, "line {i}")?;
    }
    println!(
        "before flush: {} calls, {} bytes handed over, {} bytes waiting",
        w.get_ref().calls,
        w.get_ref().bytes,
        w.buffer().len()
    );
    w.flush()?;
    println!(
        "after flush: {} bytes in {} write calls",
        w.get_ref().bytes,
        w.get_ref().calls
    );
    Ok(())
}

check-impls.rs.code:
use std::fs::File;
use std::io::{self, BufRead, BufReader, Cursor, Read, Seek, Write};
use std::marker::PhantomData;

/// `has!(Trait, Type)` is true when `Type` implements `Trait`: an inherent constant that only
/// exists under the bound beats the trait constant that is always there.
macro_rules! has {
    ($tr:path, $t:ty) => {{
        #[allow(dead_code)]
        trait No {
            const YES: bool = false;
        }
        impl<T: ?Sized> No for T {}
        struct P<T: ?Sized>(PhantomData<T>);
        #[allow(dead_code)]
        impl<T: ?Sized + $tr> P<T> {
            const YES: bool = true;
        }
        <P<$t>>::YES
    }};
}

/// Read, Write, BufRead, Seek for one type.
macro_rules! row {
    ($t:ty) => {
        [
            has!(Read, $t),
            has!(Write, $t),
            has!(BufRead, $t),
            has!(Seek, $t),
        ]
    };
}

fn main() {
    //                          Read   Write  BufRead Seek
    assert_eq!(row!(File), [true, true, false, true]);
    assert_eq!(row!(BufReader<File>), [true, false, true, true]);
    assert_eq!(row!(&[u8]), [true, false, true, false]);
    assert_eq!(row!(Cursor<Vec<u8>>), [true, true, true, true]);
    assert_eq!(row!(Vec<u8>), [false, true, false, false]);
    assert_eq!(row!(io::Stdin), [true, false, false, false]);
    assert_eq!(row!(io::StdinLock<'static>), [true, false, true, false]);
    assert_eq!(row!(io::Stdout), [false, true, false, false]);
    println!("ok");
}

